\subsection{Plot twists leak, and a twist-free outline removes the leak}
\label{sec:res_e2}

\input{tables/e2}

\begin{figure}[t]
    \centering
    \includegraphics[width=0.75\linewidth]{figures/e2_twist_2afc.png}
