import fitz
from PIL import Image
d=fitz.open('main.pdf')
for i,p in enumerate(d):
    t=p.get_text()
    for k in ['\nReferences','Conclusion\n','Prompts\n','Discussion\n']:
        if k in t: print(i+1,repr(k))
ims=[]
for p in d:
    pix=p.get_pixmap(dpi=40); ims.append(Image.frombytes('RGB',[pix.width,pix.height],pix.samples))
w,h=ims[0].size;cols=6;rows=(len(ims)+cols-1)//cols
S=Image.new('RGB',(w*cols,h*rows),'white')
for i,im in enumerate(ims): S.paste(im,((i%cols)*w,(i//cols)*h))
S.save('/tmp/sheet.png')
EOF

